<?php
session_start();require_once 'dbconfig.php';if(!isset($_SESSION['mgrid'])){header('Location: mlogin.php');exit;}$mid=(int)$_SESSION['mgrid'];$message='';$did=(int)($_POST['doctor']??0);$date=$_POST['dateselected']??'';$allowed=['Bekliyor','Onaylandı','Tamamlandı','İptal Edildi'];$doctors=$conn->prepare('SELECT DISTINCT d.DID,d.Name FROM doctor d INNER JOIN doctor_availability da ON da.DID=d.DID INNER JOIN manager_clinic mc ON mc.CID=da.CID WHERE mc.MID=? ORDER BY d.Name');$doctors->bind_param('i',$mid);$doctors->execute();$doctorResult=$doctors->get_result();if(isset($_POST['save'])){$ids=$_POST['appointment_id']??[];$statuses=$_POST['status']??[];$update=$conn->prepare("UPDATE book b INNER JOIN manager_clinic mc ON mc.CID=b.CID SET b.Status=?, b.active_slot_key=CASE WHEN ? IN ('İptal Edildi','Tamamlandı') THEN NULL ELSE b.active_slot_key END WHERE b.appointment_id=? AND mc.MID=?");for($i=0;$i<min(count($ids),count($statuses));$i++){$id=(int)$ids[$i];$status=trim($statuses[$i]);if($id>0&&in_array($status,$allowed,true)){$update->bind_param('ssii',$status,$status,$id,$mid);$update->execute();}}$update->close();$message='Randevu durumları güncellendi.';}$rows=[];if(isset($_POST['load'])&&$did>0&&$date!==''){$q=$conn->prepare('SELECT b.appointment_id,b.Username,b.Fname,b.DOV,b.appointment_time,b.Timestamp,b.Status FROM book b INNER JOIN manager_clinic mc ON mc.CID=b.CID WHERE b.DOV=? AND b.DID=? AND mc.MID=? ORDER BY b.appointment_time,b.Timestamp');$q->bind_param('sii',$date,$did,$mid);$q->execute();$res=$q->get_result();while($r=$res->fetch_assoc())$rows[]=$r;$q->close();}?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Randevu Durumu | Appointment</title><link rel="stylesheet" href="adminmain.css"><style>.wrap{width:min(1100px,calc(100% - 32px));margin:30px auto 60px}.head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:20px}.head h1{margin:5px 0 7px;font-size:32px}.head p{margin:0;color:var(--admin-muted)}.card{padding:22px;margin-bottom:16px}.filters{display:grid;grid-template-columns:1fr 1fr auto;gap:14px;align-items:end}.field label{display:block;margin-bottom:7px;font-size:12px;font-weight:800}.table-card{padding:0;overflow:hidden}.top{padding:18px 20px;border-bottom:1px solid var(--admin-border);font-weight:800}.table-wrap{overflow:auto}.tbl{width:100%;border-collapse:collapse;min-width:800px}.tbl th,.tbl td{padding:12px 14px;border-bottom:1px solid var(--admin-border);text-align:left;font-size:13px}.tbl th{background:#f8fafc;color:#657084;font-size:10px;text-transform:uppercase}.tbl select{min-width:130px}.status{padding:5px 8px;border-radius:999px;font-size:11px;font-weight:800}.ok{background:#e7f6ec;color:#16713a}.wait{background:#fff3cd;color:#856404}.done{background:#e7f0ff;color:#2457a6}.cancel{background:#fde8e8;color:#a32929}.empty{padding:35px;text-align:center;color:var(--admin-muted)}.msg{margin-bottom:16px}.actions{display:flex;justify-content:flex-end;margin-top:16px}@media(max-width:650px){.wrap{width:calc(100% - 20px);margin-top:18px}.head{align-items:flex-start;flex-direction:column}.filters{grid-template-columns:1fr}.filters .admin-button{width:100%}}
</style></head><body><header class="admin-topbar"><a class="admin-brand" href="mgrmenu.php"><img src="../images/cal.png" width="30" height="30" alt="Appointment"><span>Appointment</span></a><nav class="admin-nav"><a href="mgrmenu.php">Panel</a><a class="active" href="changebookingstatus.php">Randevular</a></nav></header><main class="wrap"><div class="head"><div><span class="admin-eyebrow">RANDEVU YÖNETİMİ</span><h1>Randevu durumları</h1><p>Doktor ve tarih seçerek bağlı olduğunuz kliniklerdeki randevuları yönetin.</p></div><a class="admin-button secondary" href="mgrmenu.php">Panele Dön</a></div><?php if($message):?><div class="alert success msg"><?php echo htmlspecialchars($message);?></div><?php endif;?><section class="admin-card card"><form method="post"><div class="filters"><div class="field"><label>Doktor</label><select name="doctor" required><option value="">Doktor seçin</option><?php while($d=$doctorResult->fetch_assoc()):?><option value="<?php echo (int)$d['DID'];?>" <?php echo $did===(int)$d['DID']?'selected':'';?>>Dr. <?php echo htmlspecialchars($d['Name']);?></option><?php endwhile;?></select></div><div class="field"><label>Tarih</label><input type="date" name="dateselected" value="<?php echo htmlspecialchars($date);?>" required></div><button class="admin-button" type="submit" name="load">Randevuları Getir</button></div></form></section><?php if(isset($_POST['load'])||isset($_POST['save'])):?><section class="admin-card table-card"><div class="top">Randevu listesi · <?php echo count($rows);?> kayıt</div><?php if(!$rows):?><div class="empty">Seçilen doktor ve tarihte randevu bulunamadı.</div><?php else:?><form method="post"><input type="hidden" name="doctor" value="<?php echo $did;?>"><input type="hidden" name="dateselected" value="<?php echo htmlspecialchars($date);?>"><div class="table-wrap"><table class="tbl"><thead><tr><th>ID</th><th>Hasta</th><th>Kullanıcı</th><th>Tarih</th><th>Saat</th><th>Durum</th></tr></thead><tbody><?php foreach($rows as $r):$s=$r['Status'];?><tr><td>#<?php echo (int)$r['appointment_id'];?><input type="hidden" name="appointment_id[]" value="<?php echo (int)$r['appointment_id'];?>"></td><td><b><?php echo htmlspecialchars($r['Fname']);?></b></td><td><?php echo htmlspecialchars($r['Username']);?></td><td><?php echo htmlspecialchars($r['DOV']);?></td><td><b><?php echo htmlspecialchars(substr($r['appointment_time'],0,5));?></b></td><td><select name="status[]"><?php foreach($allowed as $o):?><option value="<?php echo htmlspecialchars($o);?>" <?php echo $s===$o?'selected':'';?>><?php echo htmlspecialchars($o);?></option><?php endforeach;?></select></td></tr><?php endforeach;?></tbody></table></div><div class="actions"><button class="admin-button" type="submit" name="save">Değişiklikleri Kaydet</button></div></form><?php endif;?></section><?php endif;?></main></body></html>